import sys
import subprocess
PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'
def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    try:
        subprocess.run(['update-alternatives', '--set', 'python', f'/usr/bin/python{python_version}'], check=True)
    except subprocess.CalledProcessError:
        try:
            subprocess.run(['pyenv', 'global', python_version], check=True)
        except subprocess.CalledProcessError:
            raise RuntimeError(f"Failed to switch to Python version {python_version}")
    sys.path.append(path_to_append)
    return sys.version.split()[0]

